themes.rules:
body {
	background: #FFFFEE url(/image/fade.png) top center repeat-x;

	color: #800000;
	font-family: arial, helvetica, sans-serif;
	font-size: 10pt;

	margin-left: 0;
	margin-right: 0;
	margin-top: 5px;

	padding-left: 5px;
	padding-right: 5px;
}
table {
	border-spacing: 1px;

	margin-left: auto;
	margin-right: auto;
}
td {
	margin: 0px;
	padding: 0px;

	font-size: 10pt;
}
hr {
	border: none;
	border-top: 1px solid #D9BFB7;

	height: 0;
}
.aboveMidAd {
  width: 468px;
  max-width: 100%;
}
#blotter {
  width: 468px;
  margin: auto;
}
#blotter td {
  vertical-align: top;
  font-size: 11px;
}
.blotter-date {
  width: 50px;
  text-align: center;
}
#blotter tfoot {
  text-align: right;
}

